-- GENERATED by `wfj generate` from data/gossip/gossip-04.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["0400656605c4550b"] = { "Korfax, dove posso trovare rottami di ⟦Dark Iron=Ferroscuro⟧?", "." },
  ["0404584a81de0dcd"] = { "Siamo stati così presi da questa guerra che alcuni di noi si sono dimenticati di trovare il tempo per l'amore.", "." },
  ["0404b267f15a2630"] = { "Cosa sto facendo? Ti manca forse l'immaginazione? Io sogno, <buon/buona> <signore/signora>, e sogno un futuro migliore per tutti noi. È chiaro: la mia è una mente visionaria.\n\nCi sono però quelli che vogliono tenerci impantanati nella banalità. Gli ho detto che sognavo, e l'Arcidruido Staghelm mi ha risposto: «Beh, il mondo ha bisogno anche di chi scava i fossi».\n\nFinché non ci strapperemo di dosso le catene della banalità, aiuterò il ⟦Cenarion Circle=Circolo Cenariano⟧ spostando questi mucchi di terra.", "." },
  ["0405cc66241b896d"] = { "Cucina", "." },
  ["040c4dbbdc792b0c"] = { "Se non lascerai la ⟦Alterac Valley=Valle d'Alterac⟧ di tua spontanea volontà, saranno i Lupi Bianchi a cacciarti!", "." },
  ["040fe4e10482bdcd"] = { "Vediamo quanto sei capace, d'accordo? Se svolgerai questo compito come piace a me, mi prenderò il tempo per insegnarti!", "." },
  ["04114865d44e004e"] = { "Oh, ciao, {class}. A quanto pare l'⟦Alliance=Alleanza⟧ mi ha chiesto di venire qui a tenere il conto di tutta questa carne cotta che la gente sta raccogliendo per via del destino incombente ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Non sembra divertente?\n\nComunque, immagino che tu voglia sapere quanta ne abbiamo. L'ultima volta che l'ho contata eravamo a $2098w su un totale di $2099w raptor arrosto necessari.", "." },
  ["041596f9266a2929"] = { "Donne...", "." },
  ["0422e0f2dd854305"] = { "Patetico.", "." },
  ["04230e75e7bea10b"] = { "Di sicuro a Darnassus c'è un sarto che può darti l'addestramento. Quando arrivi, chiedi a una delle ⟦Sentinels=Sentinelle⟧ di Darnassus di indicarti un sarto.", "." },
  ["04272abb5d01f7f6"] = { "Quando un fulmine colpisce l'oceano, perché non muoiono tutti i pesci?", "." },
  ["0429e6096bc3ff78"] = { "La fine dei giorni è giunta! Che la terra accolga la mia carne e le mie ossa.", "." },
  ["042a6d92d0d971b8"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare un ⟦Wild Leather Helmet=Elmetto di Cuoio Selvatico⟧?", "." },
  ["043089abab761be1"] = { "Il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧ protegge il fianco orientale del ⟦Field of Strife=Pian della Discordia⟧.\n\nÈ sotto il controllo dell'⟦Alliance=Alleanza⟧.", "." },
  ["0430ee7f4cd20006"] = { "Salute! Se sei qui per accedere agli schemi di ingegneria gnomesca, tieni pronta la tua Tessera di Socio degli Ingegneri Gnomi per la verifica.", "." },
  ["044feb87d63232c3"] = { "Il tuo sangue scorre per il bene dell'umanità, infedele!", "." },
  ["04549609616c244d"] = { "Osserva la saggezza e la conoscenza della bestia, e vedrai te <stesso/stessa>. Osserva come fa il gufo, impara l'astuzia dalla tigre dai denti a sciabola, incarna il possente spirito del lupo.", "." },
  ["04591db7e2cb5c0e"] = { "Attenzione! Attaccano i Kolkar!", "." },
  ["045cbfeaedfffa1f"] = { "Sissignora, gli affari vanno a gonfie vele!", "." },
  ["045e9690bf03f0a0"] = { "Immagino di potertelo insegnare. Il tannino d'ogre probabilmente lo troverai solo qui, ma il resto si trova quasi ovunque!", "." },
  ["0463bfa367acb8e9"] = { "Allora devi andare a Orgrimmar. La strada nord che esce da ⟦Razor Hill=Tranciacolle⟧ porta dritta lì. Parla con uno dei grunt sul posto e ti darà altre indicazioni.", "." },
  ["04662fa3b1e236ff"] = { "Lo so, lo so, sono qui in mezzo al nulla!\n\nIn realtà vivo a ⟦Ratchet=Porto Paranco⟧, ma dopo che il mio zeppelin si è schiantato qui, ho pensato che tanto valeva cominciare le ricerche che mi avevano portato fin qui!", "." },
  ["0466c83c13920da6"] = { "Ti prego, dimmi di più sugli ippogrifi.", "." },
  ["0467081f2aaa290f"] = { "Dov'è l'anziano Splitrock?", "." },
  ["046d179af467e865"] = { "La tua abilità nel preparare pozioni deve migliorare prima che tu possa unirti ai miei studenti. Nel frattempo, forse ⟦Sylvanna Forestmoon=Sylvanna Erbaluna⟧ o ⟦Milla Fairancora=Milla Ferancora⟧ possono aiutarti, proprio lì.", "." },
  ["04771e61596b0d33"] = { "Venite, miseri mortali. Venite ad affrontare la vostra fine. I segreti di ⟦Ahn'Qiraj=Ahn'qiraj⟧ moriranno con Roman'khan!", "." },
  ["04776961d5829808"] = { "Tanto tempo fa, io e le mie sorelle driadi entrammo in queste grotte per liberare lo spirito tormentato di mio zio, Zaetar. Ma la corruzione che già si era diffusa in queste caverne ci sopraffece presto, e cademmo anche noi.\n\nEravamo destinate a vagare per questi passaggi, con le tossine che ci avvelenavano la mente...\n\nAnche se ora il mio spirito può riposare, so di aver fallito nella mia missione. È una grande tristezza quella che devo portare...", "." },
  ["047bd7b6f8fa9160"] = { "Bel tentativo, ma ti serve più esperienza prima di addestrarti con me! Torna in trincea!", "." },
  ["0484cbdca305c452"] = { "Mmm, non ho rivestimenti di mithril. Li ho finiti. È tutto quello che ti serve per riparare A-Me? Oh, sarebbe fantastico!\n\nI rivestimenti di mithril non sono troppo difficili da trovare, nella civiltà. Basta chiedere a un ingegnere esperto di fartene uno. Credo che servano alcuni lingotti di mithril, ma se puoi darmi una mano, farò in modo che tu sia ben <ricompensato/ricompensata>!", "." },
  ["048ee8f1a126dabe"] = { "Conferma i miei sospetti, {name}. Portami 8 ⟦Fel Moss=Vilmuschio⟧.", "." },
  ["049815b2782988dc"] = { "Loro stare in ⟦Magic Quarter=Quartiere della Magia⟧. Cercali in edificio con teschio che fa paura.", "." },
  ["049bad0f881fb22c"] = { "Questa oscura corruzione fa proprio male agli affari.", "." },
  ["04a669d81379d8bd"] = { "Chi controlla la East Frostwolf Tower?", "." },
  ["04a827e2b147eb59"] = { "%s macina le perle che {name} gli ha dato...", "." },
  ["04aa2714094b17ba"] = { "Finalmente la corruzione che mi legava a questo luogo non mi tiene più...", "." },
  ["04abe4e043fff891"] = { "{class}, anche i nostri guerrieri ed esploratori più robusti avranno bisogno delle arti curative nella guerra che ci attende ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. E quando non ci sarà guarigione magica disponibile, dovranno contare sui nostri sforzi qui.\n\nFinora ho raccolto $2088w bende di telarunica, su $2090w necessarie. Se sei <disposto/disposta> a farlo, dovremmo parlare ancora di come puoi fare la tua parte.", "." },
  ["04afbcdf4866b419"] = { "Distruggi!", "." },
  ["04b150e1fe6963b8"] = { "Chi controlla la Torre di Brinarossa?", "." },
  ["04b4bd96e3e6032c"] = { "L'istruttrice dei Ladri si chiama Marion Call. La trovi al piano di sopra, nella sala di lettura della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, sul margine sud-est della città.", "." },
  ["04b50438ffb5375f"] = { "Allievo lavorerà di più, maestro!", "." },
  ["04bbb3122d0433ae"] = { "Cos'è quella cosa all'orizzonte? Una nave nemica, di sicuro! Fuoco!", "." },
  ["04c4ad3bb326c13b"] = { "È tutto perduto...", "." },
  ["04c5527c0ae28ed3"] = { "Non così <sicuro/sicura> di te senza il Purifier, eh?", "." },
  ["04c7e005093a84c8"] = { "Vivo solo per servire il padrone.", "." },
  ["04c7f823445ab590"] = { "Prendi ogni parola che dico e imprimila nella memoria. Finché i nostri nemici non saranno estirpati, non dobbiamo mai sottrarci a un'occasione per accrescere il nostro sapere. Rinforza la tua armatura e non abbassare mai la guardia.", "." },
  ["04c84b2cbac1acf9"] = { "Tanti caduti. E tanti altri ne dovremo perdere prima che questa battaglia finisca.", "." },
  ["04cbdcf8b8250cf7"] = { "È Rupert Boch che cerchi. Lui e il suo seguito hanno una stanza al piano di sopra della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, sul lato sud-est di Brill.", "." },
  ["04d4a0abdcfb3074"] = { "Mmm... Credo che mi serva un'esca migliore. Darò un'occhiata al carro di mio padre.", "." },
  ["04d7f18b21729bf3"] = { "Ladri? Smettetela di nascondervi e affrontatemi!", "." },
  ["04d9bff2db212642"] = { "Grrrr... carne fresca!", "." },
  ["04dbc47b72c95ebf"] = { "%s afferra il suo pugnale avvelenato!", "." },
  ["04de2cde41cf1138"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ è già arrivata, dici? Dove si trova?", "." },
  ["04ea65ce1faa9229"] = { "Ora, in quale di questi l'avrò messo...", "." },
  ["04ecf2bec40b0a15"] = { "⟦Winterhoof=Zoccolo Artico⟧? Ho sentito che se la spassa a ⟦Booty Bay=Baia del Bottino⟧.", "." },
  ["04f8236d347f754a"] = { "Un diario dalle pagine ingiallite è aperto sull'ultima annotazione:\n\n«Non so cosa succederà adesso che Harold si è trasformato. Ci ho messo tutte le mie forze per trascinarlo nell'unico posto che ho trovato in grado di rinchiuderlo e tenerlo ben chiuso. Ho nascosto la chiave addosso a me, e prego che funzioni...\n\nSpero di riuscire ad andarmene da qui, ma mi servono soldi per farlo. Credo che la nostra roba sia tutta nell'armadietto... e ora che ci penso, la chiave non ce l'ha addosso Harold?\n\nCi dormirò sopra, ora non mi reggo in piedi.»", "." },
})
